/*
 * SIO6509_$RCV - 6509 receive interrupt: hand the received byte to SIO
 *
 * Original address: 0x00E1D53E (SAU2 map)
 * Size: 72 bytes (0x00E1D53E .. 0x00E1D585)
 * Generated by: Claude Opus 5.5
 *
 * Called by SIO6509_$INT1_RTE (sio6509/sau2/int1_rte.s) with the channel
 * record's VA pushed.  A5 = 0xE2DEB8 (SIO2681_$DATA, the SIO_IO module).
 *
 * Frame (link.w A6,-0x4): (0x8,A6) chan (A2).
 *
 * Blocks:
 *   0x00E1D550-0x00E1D558  D2w = the status byte at regs+1, zero-extended;
 *                          bit 7 clear -> nothing received, return
 *   0x00E1D55A-0x00E1D576  SIO_$I_RCV(chan->sio_desc, regs[3],
 *                          SIO2681_$DATA.sio6509_rcv_flags[(status >> 4) & 7])
 *                          with a word result slot reserved
 */

#include "sio6509/sio6509_internal.h"

void SIO6509_$RCV(m68k_ptr_t chan_va)
{
    sio6509_chan_t *chan;               /* A2 */
    volatile uint8_t *regs;             /* A0 */
    uint16_t status;                    /* D2w */

    /* 0x00E1D54C-0x00E1D554 */
    chan = (sio6509_chan_t *)ARCH_VA_TO_PTR(chan_va);
    regs = (volatile uint8_t *)ARCH_VA_TO_PTR(chan->regs);
    status = regs[1];

    /* 0x00E1D558: bpl on the byte */
    if ((status & 0x80) != 0) {
        /* 0x00E1D55A-0x00E1D576 */
        SIO_$I_RCV((sio_desc_t *)ARCH_VA_TO_PTR(chan->sio_desc), regs[3],
                   SIO2681_$DATA.sio6509_rcv_flags[(status >> 4) & 7]);
    }
}
